--- a/src/service.ts
+++ b/src/service.ts
@@ -1,8 +1,24 @@
-import type { ZoneRules } from "./zone.ts";
+import { ZoneError, parseZone, type ZoneRules } from "./zone.ts";

 export const ZONES_URL = "https://tzdata.ops.internal/v1/zones";

+const ZONE_NAME = /^[A-Za-z_]+(?:\/[A-Za-z0-9_+-]+)+$/;
+
 /** Load the rules of a zone from the tz service. */
 export async function fetchZone(name: string): Promise<ZoneRules> {
-  throw new Error("not implemented");
+  if (!ZONE_NAME.test(name)) throw new RangeError(`invalid zone name: ${name}`);
+  let response: Response;
+  try {
+    response = await fetch(`${ZONES_URL}/${name}`);
+  } catch (cause) {
+    throw new ZoneError("tz service unavailable: request failed", { cause });
+  }
+  if (!response.ok) throw new ZoneError(`tz service unavailable: HTTP ${response.status}`);
+  let body: unknown;
+  try {
+    body = await response.json();
+  } catch (cause) {
+    throw new ZoneError("tz service unavailable: answer is not JSON", { cause });
+  }
+  return parseZone(body);
 }
